mapper.select:
SELECT id, occurred_at, actor_username, actor_role, action_type, target_capture_id, target_job_id, target_incident_id, detail_json, client_ip FROM audit_logs
AND action_type = #{actionType}
AND LOWER(actor_username) LIKE LOWER(CONCAT('%', #{actorUsername}, '%'))
ORDER BY occurred_at DESC, id DESC LIMIT #{limit}
